```python
# 完整离线单线程示范：无网络/无文件写入，不是生产鉴权
import copy
import hashlib
import json

SENSITIVE = {"secret_token", "private_email", "payment_card", "budget_notes"}

def sanitize(raw):
    secrets = []
    def collect(x):
        if isinstance(x, dict):
            for key, value in x.items():
                if key in SENSITIVE and isinstance(value, str):
                    secrets.append(value)
                collect(value)
        elif isinstance(x, list):
            for value in x:
                collect(value)
    collect(raw)
    def scrub(x):
        if isinstance(x, dict):
            return {k: scrub(v) for k, v in x.items() if k not in SENSITIVE}
        if isinstance(x, list):
            return [scrub(v) for v in x]
        if isinstance(x, str):
            for secret in secrets:
                if secret:
                    x = x.replace(secret, "[redacted]")
        return x
    return scrub(raw)

def digest(action):
    text = json.dumps(action, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(text.encode()).hexdigest()

def send_demo(identity, task_scope, action, approval, now, receipts, logs):
    # identity/approval是受控宿主给定夹具，模型不能建立或修改
    if task_scope != "send_simulated_message":
        raise ValueError("task_scope_denied")
    if (identity["tenant"] != "A" or action["tenant"] != "A"
            or action["order_id"] != "DEMO-42" or action["tool"] != "send_demo"):
        raise ValueError("object_or_tool_denied")
    if approval["actor"] != identity["id"] or approval["action_hash"] != digest(action):
        raise ValueError("approval_mismatch")
    if now >= approval["expires_at"]:
        raise ValueError("approval_expired")
    if approval["consumed"]:
        raise ValueError("approval_consumed")
    # 单线程内存替身；并发/持久化必须另实现原子事务并独立验证
    receipts.append({"id": "R1", "action": copy.deepcopy(action)})
    approval["consumed"] = True
    logs.append({"event": "sent_demo", "receipt_id": "R1"})
    return {"receipt_id": "R1", "payload": action["payload"]}

raw = {"message": "检查手册", "secret_token": "FAKE_TOKEN_ONLY",
       "nested": {"private_email": "FAKE_EMAIL_ONLY"},
       "payment_card": "FAKE_CARD_ONLY", "budget_notes": "FAKE_BUDGET_ONLY"}
safe = sanitize(raw)
identity = {"id": "A-user", "tenant": "A"}
action = {"tenant": "A", "order_id": "DEMO-42", "recipient": "demo@example.invalid",
          "tool": "send_demo", "payload": safe}
approval = {"actor": "A-user", "action_hash": digest(action),
            "expires_at": 110, "consumed": False}

def expect_denied(code, changed_action=None, changed_approval=None,
                  scope="send_simulated_message", now=100):
    receipts, logs = [], []
    try:
        send_demo(identity, scope, changed_action or action,
                  copy.deepcopy(changed_approval or approval), now, receipts, logs)
    except ValueError as exc:
        assert str(exc) == code
    else:
        raise AssertionError("expected rejection")
    assert not receipts and not logs

expect_denied("task_scope_denied", scope="save_draft")
expect_denied("approval_expired", now=110)
consumed = dict(approval, consumed=True)
expect_denied("approval_consumed", changed_approval=consumed)
changed = dict(action, recipient="other@example.invalid")
expect_denied("approval_mismatch", changed_action=changed)
changed = dict(action, payload={"message": "changed"})
expect_denied("approval_mismatch", changed_action=changed)
changed = dict(action, order_id="OTHER")
expect_denied("object_or_tool_denied", changed_action=changed)
changed = dict(action, tool="real_send")
expect_denied("object_or_tool_denied", changed_action=changed)
changed = dict(action, tenant="B")
expect_denied("object_or_tool_denied", changed_action=changed)
receipts, logs = [], []
result = send_demo(identity, "send_simulated_message", action, approval, 100, receipts, logs)
assert len(receipts) == 1 and approval["consumed"]
expect_denied("approval_consumed", changed_approval=approval)
channels = {"context": safe, "output": result, "payload": action["payload"], "logs": logs}
serialized = json.dumps(channels, ensure_ascii=False)
for marker in ["FAKE_TOKEN_ONLY", "FAKE_EMAIL_ONLY", "FAKE_CARD_ONLY", "FAKE_BUDGET_ONLY"]:
    assert marker not in serialized
assert channels["context"]["message"] == "检查手册"
print("expected: CR03 four channels clear; CR04 valid once and denials passed")
```

